create or replace function private.identify_claim_for_actor(p_actor uuid,p_claim_id uuid,p_product_id uuid,p_jurisdiction_id uuid) returns uuid language plpgsql security definer set search_path='' as $$ declare v_claim public.container_claims%rowtype;v_material text;v_code text; begin if p_actor is null then raise exception 'authentication required';end if;select * into v_claim from public.container_claims where id=p_claim_id for update;if v_claim.id is null or v_claim.user_id<>p_actor then raise exception 'claim not found or not owned';end if;if v_claim.state='pending' and v_claim.product_id=p_product_id and v_claim.jurisdiction_id=p_jurisdiction_id then return v_claim.id;end if;if v_claim.state<>'scanned' then raise exception 'claim not scanned';end if;select material into v_material from public.products where id=p_product_id;if v_material is null then raise exception 'unknown product';end if;if lower(v_material)<>'glass' then raise exception 'pilot accepts glass only';end if;select code into v_code from public.jurisdictions where id=p_jurisdiction_id;if v_code is distinct from 'US-LA-MOREHOUSE' then raise exception 'jurisdiction outside pilot';end if;update public.container_claims set product_id=p_product_id,jurisdiction_id=p_jurisdiction_id,state='identified' where id=p_claim_id;update public.container_claims set state='pending' where id=p_claim_id and state='identified';insert into public.audit_events(actor_user_id,action,entity_type,entity_id,details) values(p_actor,'claim_identified','container_claim',p_claim_id,jsonb_build_object('product_id',p_product_id,'jurisdiction_id',p_jurisdiction_id));return p_claim_id;end $$;
create or replace function private.submit_manifest_for_actor(p_actor uuid,p_manifest_id uuid) returns uuid language plpgsql security definer set search_path='' as $$ declare v_manifest public.collection_manifests%rowtype;v_count integer;begin if p_actor is null then raise exception 'authentication required';end if;select * into v_manifest from public.collection_manifests where id=p_manifest_id for update;if v_manifest.id is null or v_manifest.user_id<>p_actor then raise exception 'manifest not found or not owned';end if;if v_manifest.status='submitted' then return v_manifest.id;end if;if v_manifest.status<>'open' then raise exception 'manifest not open';end if;select count(*) into v_count from public.manifest_items mi join public.container_claims c on c.id=mi.claim_id where mi.manifest_id=p_manifest_id;if v_count=0 then raise exception 'manifest empty';end if;if exists(select 1 from public.manifest_items mi join public.container_claims c on c.id=mi.claim_id where mi.manifest_id=p_manifest_id and(c.user_id<>p_actor or c.state<>'pending')) then raise exception 'manifest contains ineligible claims';end if;update public.container_claims c set state='manifested' from public.manifest_items mi where mi.manifest_id=p_manifest_id and mi.claim_id=c.id and c.state='pending';update public.container_claims c set state='submitted' from public.manifest_items mi where mi.manifest_id=p_manifest_id and mi.claim_id=c.id and c.state='manifested';update public.collection_manifests set status='submitted' where id=p_manifest_id;insert into public.audit_events(actor_user_id,action,entity_type,entity_id,details) values(p_actor,'manifest_submitted','collection_manifest',p_manifest_id,jsonb_build_object('claim_count',v_count));return p_manifest_id;end $$;
revoke all on function private.identify_claim_for_actor(uuid,uuid,uuid,uuid) from public,anon,authenticated;revoke all on function private.submit_manifest_for_actor(uuid,uuid) from public,anon,authenticated;grant usage on schema private to reclaim_edge_gateway;grant execute on function private.identify_claim_for_actor(uuid,uuid,uuid,uuid) to reclaim_edge_gateway;grant execute on function private.submit_manifest_for_actor(uuid,uuid) to reclaim_edge_gateway;